% init_params.m
m  = 0.025;                      % kg
Jx = 4.856e-3; Jy = 4.856e-3; Jz = 8.801e-3;
J  = [Jx Jy Jz];
g  = 9.81;

% Position controller gains (eq. 20)
Kp_xi = diag([60 60 60]);
Kd_xi = diag([6 6 6]);
Ki_xi = diag([0.1 0.1 0.1]);

% Attitude controller gains (eq. 27)
Kp_q = diag([2000 2000 2000]);
Kd_q = diag([10 10 10]);
Ki_q = diag([10 10 5]);

q3r_des = 0;   % desired yaw-related quaternion component (fixed to 0 as in paper)

% Initial conditions
xi0    = [1.8; 2.27; 0.6];
xidot0 = [0;0;0];
q0_init = [1;0;0;0];   % identity quaternion
omega0  = [0;0;0];
%%
t = out.xi_r_log.Time; %[output:88777b95]
xi_r = squeeze(out.xi_r_log.Data); %[output:2b3745a0]
xi   = squeeze(out.xi_log.Data); %[output:28084be4]
%%
size(t) %[output:630113bd]
size(xi_r) %[output:9e99aba7]
size(xi) %[output:7a5387e4]
%%
figure; %[output:5f2ff10d]

plot(t, xi_r(1,:), 'LineWidth', 1.5); %[output:5f2ff10d]
hold on; %[output:5f2ff10d]
plot(t, xi(1,:), '--', 'LineWidth', 1.5); %[output:5f2ff10d]

grid on; %[output:5f2ff10d]
xlabel('Time (s)'); %[output:5f2ff10d]
ylabel('X Position (m)'); %[output:5f2ff10d]
title('X Position Tracking'); %[output:5f2ff10d]
legend('Desired x_r','Actual x'); %[output:5f2ff10d]
%%
figure; %[output:1a261ce4]

plot(t, xi_r(2,:), 'LineWidth', 1.5); %[output:1a261ce4]
hold on; %[output:1a261ce4]
plot(t, xi(2,:), '--', 'LineWidth', 1.5); %[output:1a261ce4]

grid on; %[output:1a261ce4]
xlabel('Time (s)'); %[output:1a261ce4]
ylabel('Y Position (m)'); %[output:1a261ce4]
title('Y Position Tracking'); %[output:1a261ce4]
legend('Desired y_r','Actual y'); %[output:1a261ce4]
%%
figure; %[output:68e3ae5f]

plot(t, xi_r(3,:), 'LineWidth', 1.5); %[output:68e3ae5f]
hold on; %[output:68e3ae5f]
plot(t, xi(3,:), '--', 'LineWidth', 1.5); %[output:68e3ae5f]

grid on; %[output:68e3ae5f]
xlabel('Time (s)'); %[output:68e3ae5f]
ylabel('Z Position (m)'); %[output:68e3ae5f]
title('Z Position Tracking'); %[output:68e3ae5f]
legend('Desired z_r','Actual z'); %[output:68e3ae5f]
%%
figure; %[output:549a47fe]

plot3(xi_r(1,:), xi_r(2,:), xi_r(3,:), 'LineWidth', 1.5); %[output:549a47fe]
hold on; %[output:549a47fe]

plot3(xi(1,:), xi(2,:), xi(3,:), '--', 'LineWidth', 1.5); %[output:549a47fe]

grid on; %[output:549a47fe]
xlabel('X (m)'); %[output:549a47fe]
ylabel('Y (m)'); %[output:549a47fe]
zlabel('Z (m)'); %[output:549a47fe]
title('Quadcopter 3D Trajectory Tracking'); %[output:549a47fe]
legend('Desired Trajectory','Actual Trajectory'); %[output:549a47fe]

view(3); %[output:549a47fe]
%%
%calculating tracking error
e = xi_r - xi;
e_norm = sqrt(sum(e.^2,1));
figure; %[output:3e229bfd]

plot(t, e_norm, 'LineWidth', 1.5); %[output:3e229bfd]

grid on; %[output:3e229bfd]
xlabel('Time (s)'); %[output:3e229bfd]
ylabel('Position Error (m)'); %[output:3e229bfd]
title('Position Tracking Error'); %[output:3e229bfd]
%%
%calculate RMSE
rmse_x = sqrt(mean((xi_r(1,:) - xi(1,:)).^2));
rmse_y = sqrt(mean((xi_r(2,:) - xi(2,:)).^2));
rmse_z = sqrt(mean((xi_r(3,:) - xi(3,:)).^2));

fprintf('RMSE X = %.6f m\n', rmse_x); %[output:5770aaf9]
fprintf('RMSE Y = %.6f m\n', rmse_y); %[output:1ac3837b]
fprintf('RMSE Z = %.6f m\n', rmse_z); %[output:5ffe829f]
%%
t = out.qr_log.Time; %[output:23f46137]
qr = out.qr_log.Data; %[output:79a84cb9]
q = squeeze(out.q_log.Data); %[output:5fbaf18e]
%%
size(t) %[output:9245abca]
size(qr) %[output:4bdfc5c3]
size(q) %[output:296fe985]
%%
figure; %[output:16479583]

plot(t, qr(:,1), 'LineWidth', 1.5); %[output:16479583]
hold on; %[output:16479583]
plot(t, q(2,:), '--', 'LineWidth', 1.5); %[output:16479583]

grid on; %[output:16479583]
xlabel('Time (s)'); %[output:16479583]
ylabel('Quaternion q_1'); %[output:16479583]
title('Quaternion q_1 Tracking'); %[output:16479583]
legend('Desired q_{1r}', 'Actual q_1'); %[output:16479583]
%%
figure; %[output:6f44971c]

plot(t, qr(:,2), 'LineWidth', 1.5); %[output:6f44971c]
hold on; %[output:6f44971c]
plot(t, q(3,:), '--', 'LineWidth', 1.5); %[output:6f44971c]

grid on; %[output:6f44971c]
xlabel('Time (s)'); %[output:6f44971c]
ylabel('Quaternion q_2'); %[output:6f44971c]
title('Quaternion q_2 Tracking'); %[output:6f44971c]
legend('Desired q_{2r}', 'Actual q_2'); %[output:6f44971c]
%%
figure; %[output:1c63e5a4]

plot(t, qr(:,3), 'LineWidth', 1.5); %[output:1c63e5a4]
hold on; %[output:1c63e5a4]
plot(t, q(4,:), '--', 'LineWidth', 1.5); %[output:1c63e5a4]

grid on; %[output:1c63e5a4]
xlabel('Time (s)'); %[output:1c63e5a4]
ylabel('Quaternion q_3'); %[output:1c63e5a4]
title('Quaternion q_3 Tracking'); %[output:1c63e5a4]
legend('Desired q_{3r}', 'Actual q_3'); %[output:1c63e5a4]
%%
e_q1 = qr(:,1) - q(2,:)';
e_q2 = qr(:,2) - q(3,:)';
e_q3 = qr(:,3) - q(4,:)';

rmse_q1 = sqrt(mean(e_q1.^2));
rmse_q2 = sqrt(mean(e_q2.^2));
rmse_q3 = sqrt(mean(e_q3.^2));

fprintf('Quaternion q1 RMSE = %.8f\n', rmse_q1); %[output:9c0027b8]
fprintf('Quaternion q2 RMSE = %.8f\n', rmse_q2); %[output:253be5b5]
fprintf('Quaternion q3 RMSE = %.8f\n', rmse_q3); %[output:0502eb80]
%%
fprintf('Quaternion q1 RMSE = %.12e\n', rmse_q1); %[output:8b021312]
fprintf('Quaternion q2 RMSE = %.12e\n', rmse_q2); %[output:0a7379fc]
fprintf('Quaternion q3 RMSE = %.12e\n', rmse_q3); %[output:0d4fb0dd]
%%
t = out.T_log.Time;
T = squeeze(out.T_log.Data);
tau = squeeze(out.tau_log.Data);
omega = squeeze(out.omega_log.Data);
%%
figure; %[output:85fc49ca]
plot(t, T, 'LineWidth', 1.5); %[output:85fc49ca]
grid on; %[output:85fc49ca]
xlabel('Time (s)'); %[output:85fc49ca]
ylabel('Thrust T (N)'); %[output:85fc49ca]
title('Total Thrust Command'); %[output:85fc49ca]
%%
figure; %[output:32fa414f]

plot(t, tau(1,:), 'LineWidth', 1.5); %[output:32fa414f]
hold on; %[output:32fa414f]
plot(t, tau(2,:), 'LineWidth', 1.5); %[output:32fa414f]
plot(t, tau(3,:), 'LineWidth', 1.5); %[output:32fa414f]

grid on; %[output:32fa414f]
xlabel('Time (s)'); %[output:32fa414f]
ylabel('Torque (N·m)'); %[output:32fa414f]
title('Control Torque'); %[output:32fa414f]
legend('\tau_x','\tau_y','\tau_z'); %[output:32fa414f]
%%
figure; %[output:7a1dc1e2]

plot(t, omega(1,:), 'LineWidth', 1.5); %[output:7a1dc1e2]
hold on; %[output:7a1dc1e2]
plot(t, omega(2,:), 'LineWidth', 1.5); %[output:7a1dc1e2]
plot(t, omega(3,:), 'LineWidth', 1.5); %[output:7a1dc1e2]

grid on; %[output:7a1dc1e2]
xlabel('Time (s)'); %[output:7a1dc1e2]
ylabel('\omega (rad/s)'); %[output:7a1dc1e2]
title('Angular Velocity'); %[output:7a1dc1e2]
legend('\omega_x','\omega_y','\omega_z'); %[output:7a1dc1e2]
%%
fprintf('Maximum thrust = %.6f N\n', max(abs(T))); %[output:1b604198]
fprintf('Minimum thrust = %.6f N\n', min(T)); %[output:49acbdb0]
fprintf('Maximum |tau_x| = %.6e N.m\n', max(abs(tau(1,:)))); %[output:72697d4e]
fprintf('Maximum |tau_y| = %.6e N.m\n', max(abs(tau(2,:)))); %[output:58c07443]
fprintf('Maximum |tau_z| = %.6e N.m\n', max(abs(tau(3,:)))); %[output:7c3c173f]
fprintf('Maximum |omega_x| = %.6e rad/s\n', max(abs(omega(1,:)))); %[output:60df5130]
fprintf('Maximum |omega_y| = %.6e rad/s\n', max(abs(omega(2,:)))); %[output:00e27a04]
fprintf('Maximum |omega_z| = %.6e rad/s\n', max(abs(omega(3,:)))); %[output:28b689ec]
%%
t = out.xi_log.Time;

xi = squeeze(out.xi_log.Data);
q  = squeeze(out.q_log.Data);
%%
figure; %[output:1afc5b5d]

plot3(xi(1,:), xi(2,:), xi(3,:), 'LineWidth', 1.5); %[output:1afc5b5d]

grid on; %[output:1afc5b5d]
axis equal; %[output:1afc5b5d]

xlabel('X (m)'); %[output:1afc5b5d]
ylabel('Y (m)'); %[output:1afc5b5d]
zlabel('Z (m)'); %[output:1afc5b5d]

title('Quadcopter Actual 3-D Trajectory'); %[output:1afc5b5d]

view(3); %[output:1afc5b5d]

